/* @lc app=leetcode id=3448 lang=kotlin */ class Solution { fun countSubstrings(s: String): Long = s.fold(Array(10) { LongArray(10) } to 0L) { (cnt, ans), ch -> (ch - '0').let { dg -> Array(10) { LongArray(10) }.also { nw -> (1..9).forEach { d -> (0 until d).forEach { r -> nw[d][(r * 10 + dg) % d] += cnt[d][r] }.let { nw[d][dg % d]++ } } }.let { nw -> nw to ans + (if (dg > 0) nw[dg][0] else 0L) } } }.second }